// === Récupération de l'item courant ===
const item = $input.item.json;

const article = item['rss.channel.item'] || {};
const channel = item.rss?.channel || {};

// === Extraction des champs de l'article ===
const titre = (article.title || '').trim();
const url = (article.link || '').trim();
const description = (article.description || '').trim();

// === Mapping du code source basé sur l'URL de l'article ===
// Méthode robuste : on matche sur le domaine de l'URL de l'article
let sourceCode = 'UNKNOWN';
if (url.includes('cert.ssi.gouv.fr')) {
  sourceCode = 'FR-CERT-01';
} else if (url.includes('cnil.fr')) {
  sourceCode = 'FR-CNIL-01';
} else if (url.includes('cyber.gouv.fr')) {
  sourceCode = 'FR-ANSSI-01';
}

// La date peut être dans pubdate, pubDate, isoDate selon les flux
const dateRaw = article.pubdate || article.pubDate || article.isoDate || null;
let datePublication = null;
if (dateRaw) {
  const d = new Date(dateRaw);
  if (!isNaN(d.getTime())) {
    datePublication = d.toISOString();
  }
}

// === Calcul du hash SHA-256 du contenu ===
const crypto = require('crypto');
const contenuPourHash = `${titre}|${description}`;
const hashContenu = crypto.createHash('sha256').update(contenuPourHash).digest('hex');

// === Détection de la langue ===
const langue = 'fr';

// === Validation minimale ===
if (!titre || !url || sourceCode === 'UNKNOWN') {
  return null;
}

// === Construction de l'objet de sortie ===
return {
  json: {
    source_code: sourceCode,
    titre: titre,
    url: url,
    description: description.substring(0, 5000),
    date_publication: datePublication,
    langue: langue,
    hash_contenu: hashContenu,
    metadata: {
      guid: article.guid?._ || article.guid || null,
      source_title: channel.title || null,
      ingested_at: new Date().toISOString()
    }
  }
};
